sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;

  // Load the Event Dashboard Summary widget dynamically
  spUtil.get('event_dashboard_summary').then(function(response) {
    c.summaryWidget = response;
  });

  $scope.selectedSection = null;

  $scope.showSection = function(section) {
    $scope.selectedSection = section;
  };
};

sp_widget.css:
.home-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px;
  text-align: center;
}

.tile-row {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 20px;
  margin-bottom: 40px;
}

.tile {
  background-color: #1f2937;
  color: #fff;
  padding: 30px 40px;
  border-radius: 10px;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(0,0,0,0.2);
  transition: all 0.3s ease;
}

.tile:hover {
  background-color: #0d6efd;
  transform: translateY(-5px);
}

.section-content {
  background: #f9f9f9;
  padding: 40px;
  border-radius: 10px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.1);
}

sp_widget.link:
function link(scope) {
  scope.selectedSection = null;

  scope.showSection = function(section) {
    scope.selectedSection = section;
  };
}
